import React from 'react';
import './ContactUs.css';

const ContactUs = () => {
  return (
    <div className="about-container">
      <div className="hero-section">
        <h1>CONTACT US</h1>
      </div>
      <div className="contact-information">
        <div className="info-block">
            <h2><b>MMD Anaalytics India Private Limited</b></h2>
            <p>202, Sulakshana by Maurya Homes<br></br>Argora Kathal More Road<br></br>Beside Dayal Petrol Pump<br></br>Kathal More, Ranchi – Jharkhand</p>
        </div>
        <hr className="divider" />
        <a href="tel:+916204958442"><b>☎ Phone: 6204958442</b></a>
        <a href="madmin@mmdai.in"><b>📧 Email: admin@mmdai.in</b></a>
      </div>
    </div>
  );
};

export default ContactUs;
